import com.example.starter.exposure.domain.Campaign;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.Optional;

/**
 * 鍏憡琛ㄦ暟鎹闂€? */
@Repository
public class CampaignRepository {

    private final JdbcTemplate jdbc;

    public CampaignRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static final RowMapper<Campaign> MAPPER = new RowMapper<>() {
        @Override
        public Campaign mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new Campaign(
                    rs.getString("campaign_id"),
                    rs.getInt("daily_total_cap"),
                    rs.getInt("per_visitor_daily_cap"),
                    rs.getLong("created_at_utc"));
        }
    };

    /**
     * 鎸夌紪鍙锋煡璇㈠叕鍛娿€?     */
    public Optional<Campaign> findById(String campaignId) {
        return jdbc.query("SELECT campaign_id, daily_total_cap, per_visitor_daily_cap, created_at_utc "
                        + "FROM campaign WHERE campaign_id = ?", MAPPER, campaignId)
                .stream()
                .findFirst();
    }

    /**
     * 鎻掑叆鍏憡锛涚紪鍙峰啿绐佺敱璋冪敤鏂逛緷鎹敮涓€绾︽潫澶勭悊銆?     */
    public void insert(Campaign campaign) {
        jdbc.update("INSERT INTO campaign (campaign_id, daily_total_cap, per_visitor_daily_cap, created_at_utc) "
                        + "VALUES (?, ?, ?, ?)",
                campaign.campaignId(),
                campaign.dailyTotalCap(),
                campaign.perVisitorDailyCap(),
                campaign.createdAtUtc());
    }
}
package com.example.starter.exposure.repo;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.time.LocalDate;

/**
 * 涓ょ骇棰濆害璐︾洰鏁版嵁璁块棶锛氬叕鍛婃煇 UTC 鏃ユ€婚搴﹁处鐩€佽瀹㈡煇 UTC 鏃ラ搴﹁处鐩€? * 鎵€鏈夊姞閿?澧炲噺鏂规硶蹇呴』鍦ㄤ簨鍔″唴璋冪敤锛屼緷璧?SELECT ... FOR UPDATE 琛岄攣涓? * CHECK (used_* &gt;= 0) 绾︽潫淇濊瘉骞跺彂涓嬩笉瓒呭崠銆佷笉鍙樿礋銆? */
@Repository
public class LedgerRepository {

    private final JdbcTemplate jdbc;

    public LedgerRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 鍏憡褰撴棩宸插崰鐢ㄩ搴︼紱璐︾洰琛屼笉瀛樺湪瑙嗕负 0銆?*/
    public int getUsedTotal(String campaignId, LocalDate utcDate) {
        Integer value = jdbc.query("SELECT used_total FROM quota_total_ledger "
                + "WHERE campaign_id = ? AND utc_date = ?",
                rs -> rs.next() ? rs.getInt(1) : null, campaignId, java.sql.Date.valueOf(utcDate));
        return value == null ? 0 : value;
    }

    /** 璁垮褰撴棩宸插崰鐢ㄩ搴︼紱璐︾洰琛屼笉瀛樺湪瑙嗕负 0銆?*/
    public int getUsedVisitor(String campaignId, String visitorId, LocalDate utcDate) {
        Integer value = jdbc.query("SELECT used_visitor FROM quota_visitor_ledger "
                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ?",
                rs -> rs.next() ? rs.getInt(1) : null,
                campaignId, visitorId, java.sql.Date.valueOf(utcDate));
        return value == null ? 0 : value;
    }

    /** 纭繚鍏憡褰撴棩璐︾洰琛屽瓨鍦紙涓嶅瓨鍦ㄥ垯浠?0 鍒涘缓锛夈€?*/
    public void ensureTotalRow(String campaignId, LocalDate utcDate) {
        jdbc.update("INSERT INTO quota_total_ledger (campaign_id, utc_date, used_total) "
                        + "SELECT ?, ?, 0 WHERE NOT EXISTS ("
                        + "SELECT 1 FROM quota_total_ledger WHERE campaign_id = ? AND utc_date = ?)",
                campaignId, java.sql.Date.valueOf(utcDate),
                campaignId, java.sql.Date.valueOf(utcDate));
    }

    /** 纭繚璁垮褰撴棩璐︾洰琛屽瓨鍦紙涓嶅瓨鍦ㄥ垯浠?0 鍒涘缓锛夈€?*/
    public void ensureVisitorRow(String campaignId, String visitorId, LocalDate utcDate) {
        jdbc.update("INSERT INTO quota_visitor_ledger (campaign_id, visitor_id, utc_date, used_visitor) "
                        + "SELECT ?, ?, ?, 0 WHERE NOT EXISTS ("
                        + "SELECT 1 FROM quota_visitor_ledger "
                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ?)",
                campaignId, visitorId, java.sql.Date.valueOf(utcDate),
                campaignId, visitorId, java.sql.Date.valueOf(utcDate));
    }

    /** 琛岄攣璇诲彇鍏憡褰撴棩宸插崰鐢ㄩ搴︼紱璐︾洰琛屼笉瀛樺湪瑙嗕负 0銆?*/
    public int lockUsedTotal(String campaignId, LocalDate utcDate) {
        Integer value = jdbc.query("SELECT used_total FROM quota_total_ledger "
                        + "WHERE campaign_id = ? AND utc_date = ? FOR UPDATE",
                rs -> rs.next() ? rs.getInt(1) : null, campaignId, java.sql.Date.valueOf(utcDate));
        return value == null ? 0 : value;
    }

    /** 琛岄攣璇诲彇璁垮褰撴棩宸插崰鐢ㄩ搴︼紱璐︾洰琛屼笉瀛樺湪瑙嗕负 0銆?*/
    public int lockUsedVisitor(String campaignId, String visitorId, LocalDate utcDate) {
        Integer value = jdbc.query("SELECT used_visitor FROM quota_visitor_ledger "
                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ? FOR UPDATE",
                rs -> rs.next() ? rs.getInt(1) : null,
                campaignId, visitorId, java.sql.Date.valueOf(utcDate));
        return value == null ? 0 : value;
    }

    /**
     * 鏉′欢鍗犵敤涓€娆″叕鍛婂綋鏃ラ搴︼細浠呭綋鍗犵敤鍚庝笉瓒呰繃 cap 鏃舵墠 +1銆?     *
     * @return 鏄惁鍗犵敤鎴愬姛锛沠alse 琛ㄧず鎬婚搴﹀凡婊?     */
    public boolean tryIncrementTotal(String campaignId, LocalDate utcDate, int cap) {
        int rows = jdbc.update("UPDATE quota_total_ledger SET used_total = used_total + 1 "
                        + "WHERE campaign_id = ? AND utc_date = ? AND used_total + 1 <= ?",
                campaignId, java.sql.Date.valueOf(utcDate), cap);
        return rows == 1;
    }

    /**
     * 鏉′欢鍗犵敤涓€娆¤瀹㈠綋鏃ラ搴︼細浠呭綋鍗犵敤鍚庝笉瓒呰繃 cap 鏃舵墠 +1銆?     *
     * @return 鏄惁鍗犵敤鎴愬姛锛沠alse 琛ㄧず璁垮棰濆害宸叉弧
     */
    public boolean tryIncrementVisitor(String campaignId, String visitorId, LocalDate utcDate, int cap) {
        int rows = jdbc.update("UPDATE quota_visitor_ledger SET used_visitor = used_visitor + 1 "
                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ? AND used_visitor + 1 <= ?",
                campaignId, visitorId, java.sql.Date.valueOf(utcDate), cap);
        return rows == 1;
    }

    /**
     * 鍗犵敤涓€娆″叕鍛婂綋鏃ラ搴︼紙+1锛夈€傝皟鐢ㄦ柟椤诲凡鎸佽閿佸苟瀹屾垚瀹归噺鏍￠獙銆?     */
    public void addTotal(String campaignId, LocalDate utcDate, int delta) {
        int rows = jdbc.update("UPDATE quota_total_ledger SET used_total = used_total + ? "
                        + "WHERE campaign_id = ? AND utc_date = ?",
                delta, campaignId, java.sql.Date.valueOf(utcDate));
        if (rows != 1) {
            throw new IllegalStateException("total ledger row missing for " + campaignId + " " + utcDate);
        }
    }

    /**
     * 鍗犵敤涓€娆¤瀹㈠綋鏃ラ搴︼紙+1锛夈€傝皟鐢ㄦ柟椤诲凡鎸佽閿佸苟瀹屾垚瀹归噺鏍￠獙銆?     */
    public void addVisitor(String campaignId, String visitorId, LocalDate utcDate, int delta) {
        int rows = jdbc.update("UPDATE quota_visitor_ledger SET used_visitor = used_visitor + ? "
                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ?",
                delta, campaignId, visitorId, java.sql.Date.valueOf(utcDate));
        if (rows != 1) {
            throw new IllegalStateException("visitor ledger row missing for "
                    + campaignId + " " + visitorId + " " + utcDate);
        }
    }

    /** 閲婃斁涓€娆″叕鍛婂綋鏃ラ搴︼紙-1锛夛紱CHECK 绾︽潫淇濊瘉涓嶅彉璐熴€?*/
    public void releaseTotal(String campaignId, LocalDate utcDate) {
        int rows = jdbc.update("UPDATE quota_total_ledger SET used_total = used_total - 1 "
                        + "WHERE campaign_id = ? AND utc_date = ?",
                campaignId, java.sql.Date.valueOf(utcDate));
        if (rows != 1) {
            throw new IllegalStateException("total ledger row missing for " + campaignId + " " + utcDate);
        }
    }

    /** 閲婃斁涓€娆¤瀹㈠綋鏃ラ搴︼紙-1锛夛紱CHECK 绾︽潫淇濊瘉涓嶅彉璐熴€?*/
    public void releaseVisitor(String campaignId, String visitorId, LocalDate utcDate) {
        int rows = jdbc.update("UPDATE quota_visitor_ledger SET used_visitor = used_visitor - 1 "
                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ?",
                campaignId, visitorId, java.sql.Date.valueOf(utcDate));
        if (rows != 1) {
            throw new IllegalStateException("visitor ledger row missing for "
                    + campaignId + " " + visitorId + " " + utcDate);
        }
    }
}
package com.example.starter.exposure.repo;

import com.example.starter.exposure.domain.Reservation;
import com.example.starter.exposure.domain.ReservationStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;
import java.util.Optional;

/**
 * 鏇濆厜棰勫崰鍗曟暟鎹闂€傚姞閿?CAS 鏂规硶蹇呴』鍦ㄤ簨鍔″唴璋冪敤銆? */
@Repository
public class ReservationRepository {

    private final JdbcTemplate jdbc;

    public ReservationRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static final RowMapper<Reservation> MAPPER = (rs, rowNum) -> new Reservation(
            rs.getString("reservation_id"),
            rs.getString("campaign_id"),
            rs.getString("visitor_id"),
            rs.getDate("utc_date"),
            ReservationStatus.valueOf(rs.getString("status")),
            rs.getLong("created_at_utc"),
            rs.getLong("expires_at_utc"),
            (Long) rs.getObject("terminal_at_utc"));

    private static final String COLUMNS =
            "reservation_id, campaign_id, visitor_id, utc_date, status, "
                    + "created_at_utc, expires_at_utc, terminal_at_utc";

    public void insert(Reservation reservation) {
        jdbc.update("INSERT INTO exposure_reservation (" + COLUMNS + ") VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                reservation.reservationId(),
                reservation.campaignId(),
                reservation.visitorId(),
                reservation.utcDate(),
                reservation.status().name(),
                reservation.createdAtUtc(),
                reservation.expiresAtUtc(),
                reservation.terminalAtUtc());
    }

    public Optional<Reservation> findById(String reservationId) {
        List<Reservation> list = jdbc.query(
                "SELECT " + COLUMNS + " FROM exposure_reservation WHERE reservation_id = ?",
                MAPPER, reservationId);
        return list.stream().findFirst();
    }

    /**
     * 琛岄攣璇诲彇棰勫崰鍗曘€?     */
    public Optional<Reservation> lockById(String reservationId) {
        List<Reservation> list = jdbc.query(
                "SELECT " + COLUMNS + " FROM exposure_reservation WHERE reservation_id = ? FOR UPDATE",
                MAPPER, reservationId);
        return list.stream().findFirst();
    }

    /**
     * 琛岄攣鏌ヨ鏌愬叕鍛婁笅宸插埌鏈燂紙now &gt;= expires_at_utc锛変絾浠嶄负 RESERVED 鐨勯鍗犲崟銆?     */
    public List<Reservation> lockExpiredReserved(String campaignId, long nowUtc) {
        return jdbc.query("SELECT " + COLUMNS + " FROM exposure_reservation "
                        + "WHERE campaign_id = ? AND status = 'RESERVED' AND expires_at_utc <= ? FOR UPDATE",
                MAPPER, campaignId, nowUtc);
    }

    /**
     * 鏉′欢 CAS锛氫粎褰撳綋鍓嶇姸鎬佷负 expect 鏃舵敼涓?target 骞惰褰曠粓鎬佹椂鍒汇€?     *
     * @return 鏄惁鏇存柊鎴愬姛锛堝苟鍙戠粓鎬佺珵浜夋椂鍙湁涓€涓繑鍥?true锛?     */
    public boolean compareAndSetStatus(String reservationId, ReservationStatus expect,
                                       ReservationStatus target, long terminalAtUtc) {
        int rows = jdbc.update("UPDATE exposure_reservation SET status = ?, terminal_at_utc = ? "
                        + "WHERE reservation_id = ? AND status = ?",
                target.name(), terminalAtUtc, reservationId, expect.name());
        return rows == 1;
    }
}
package com.example.starter.exposure.repo;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * 鍐欐搷浣滃箓绛夎褰曟暟鎹闂€俽equest_id 鍏ㄥ眬鍞竴锛? * 寮傚弬閲嶆斁鐢辨湇鍔″眰姣斿鎸囩汗鍚庤繑鍥?409锛屽け璐ュ洖婊氫笉鍗犻敭銆? */
@Repository
public class IdempotencyRepository {

    /**
     * 骞傜瓑璁板綍瑙嗗浘銆?     *
     * @param requestId          骞傜瓑閿?     * @param operation          鎿嶄綔绫诲瀷
     * @param requestFingerprint 璇锋眰鍙傛暟鎸囩汗锛堜笉鍚?requestId锛?     * @param responseJson       鍘熸垚鍔熷搷搴?JSON
     */
    public record IdempotencyRecord(String requestId, String operation,
                                    String requestFingerprint, String responseJson) {
    }

    private static final RowMapper<IdempotencyRecord> MAPPER = (rs, rowNum) -> new IdempotencyRecord(
            rs.getString("request_id"),
            rs.getString("operation"),
            rs.getString("request_fingerprint"),
            rs.getString("response_json"));

    private final JdbcTemplate jdbc;

    public IdempotencyRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 琛岄攣璇诲彇骞傜瓑璁板綍锛涗笉瀛樺湪杩斿洖 empty銆?*/
    public Optional<IdempotencyRecord> lockById(String requestId) {
        List<IdempotencyRecord> list = jdbc.query(
                "SELECT request_id, operation, request_fingerprint, response_json "
                        + "FROM idempotency_record WHERE request_id = ? FOR UPDATE",
                MAPPER, requestId);
        return list.stream().findFirst();
    }

    /** 鏅€氳鍙栵紙鏃犻攣锛夛紝鐢ㄤ簬骞跺彂鍚岄敭绔炰簤涓鍙栬儨鍑鸿€呭凡鎻愪氦鐨勮褰曘€?*/
    public Optional<IdempotencyRecord> findById(String requestId) {
        List<IdempotencyRecord> list = jdbc.query(
                "SELECT request_id, operation, request_fingerprint, response_json "
                        + "FROM idempotency_record WHERE request_id = ?",
                MAPPER, requestId);
        return list.stream().findFirst();
    }

    public void insert(IdempotencyRecord record, long createdAtUtc) {
        jdbc.update("INSERT INTO idempotency_record "
                        + "(request_id, operation, request_fingerprint, response_json, created_at_utc) "
                        + "VALUES (?, ?, ?, ?, ?)",
                record.requestId(),
                record.operation(),
                record.requestFingerprint(),
                record.responseJson(),
                createdAtUtc);
    }
}

