                    if (activityId != null) {
                        config = activityConfigRepository.findConfig(activityId, utcDate)
                                .orElseThrow(() -> new ApiException(HttpStatus.CONFLICT,
                                        "activity hourly budget not configured: activity="
                                                + activityId + " utcDate=" + utcDate));
                    }

