        assertEquals(2, history.entries().get(1).version());
        assertEquals("req-cfg3", history.entries().get(1).requestId());

        // 不存在的活动 404
        assert404(() -> configure("req-none", "nope", DAY, 0, budgetsOf(1, 1)));
